"use strict";const ASTEROID_TYPES={LIGHT:{level:1,color:"#84cc16",hp:10,radius:20,fallSpeed:70},MED:{level:2,color:"#15803d",hp:20,radius:28,fallSpeed:50},BLUE:{level:3,color:"#3b82f6",hp:35,radius:30,fallSpeed:50},PURPLE:{level:4,color:"#a855f7",hp:50,radius:38,fallSpeed:40},RED:{level:5,color:"#ef4444",hp:100,radius:46,fallSpeed:30}},SPLIT_MAP={1:null,2:"LIGHT",3:"MED",4:"BLUE",5:"PURPLE"};class Asteroid{constructor(t,e,s,i=null,n=null){if(this.x=t,this.y=e,this.type=ASTEROID_TYPES[s],this.radius=this.type.radius,this.hp=this.type.hp,i!==null&&n!==null)this.vx=i,this.vy=n;else{const r=this.type.fallSpeed,a=Math.random()*Math.PI*.2+Math.PI*.4;this.vx=Math.cos(a)*r*.3*(t<window.innerWidth/2?1:-1),this.vy=Math.sin(a)*r}this.createdAt=Date.now(),this.rotation=0,this.rotationSpeed=(Math.random()-.5)*2,this.vertices=this.generateVertices()}generateVertices(){const e=[];for(let s=0;s<10;s++){const i=s/10*Math.PI*2,n=.15,r=this.radius*(1-n+Math.random()*n*2);e.push({x:Math.cos(i)*r,y:Math.sin(i)*r})}return e}update(t,e){const s=e?.5:1;return this.vy<this.type.fallSpeed&&Date.now()-this.createdAt>500&&(this.vy=this.type.fallSpeed),this.x+=this.vx*s*t,this.y+=this.vy*s*t,this.rotation+=this.rotationSpeed*t,!(this.y>window.innerHeight+this.radius*2||this.x<-this.radius*2||this.x>window.innerWidth+this.radius*2)}draw(t){t.save(),t.translate(this.x,this.y),t.rotate(this.rotation),t.beginPath();for(let e=0;e<this.vertices.length;e++)e===0?t.moveTo(this.vertices[e].x,this.vertices[e].y):t.lineTo(this.vertices[e].x,this.vertices[e].y);t.closePath(),t.fillStyle="rgba(15, 24, 36, 0.5)",t.fill(),t.strokeStyle=this.type.color,t.lineWidth=2,t.stroke(),t.font=`bold ${this.radius*.7}px Arial`,t.textAlign="center",t.textBaseline="middle",t.fillStyle="rgba(0,0,0,0.8)",t.fillText(this.hp,1,1),t.fillStyle="#ffffff",t.fillText(this.hp,0,0),t.restore()}hit(t){return this.hp-=t,this.hp<=0}split(){const t=SPLIT_MAP[this.type.level];if(!t)return[];const e=[],s=80+Math.random()*60,i=s*(.8+Math.random()*.2),n=s*.1,r=-80-Math.random()*40;return e.push(new Asteroid(this.x,this.y,t,-n*Math.random(),i+r)),e.push(new Asteroid(this.x,this.y,t,n*Math.random(),i+r)),e}getBounds(){return{x:this.x-this.radius,y:this.y-this.radius,width:this.radius*2,height:this.radius*2}}}class AsteroidManager{constructor(){this.asteroids=[],this.lastSpawnTime=0,this.spawnInterval=2e3,this.minSpawnInterval=800}update(t,e,s){const i=Math.max(this.minSpawnInterval,this.spawnInterval-s*2);for(let n=this.asteroids.length-1;n>=0;n--)this.asteroids[n].update(t,e)||this.asteroids.splice(n,1)}trySpawn(t){const e=Date.now(),s=Math.max(this.minSpawnInterval,this.spawnInterval-t*2);e-this.lastSpawnTime>s&&(this.lastSpawnTime=e,this.spawn())}spawnInitial(){const t=this.getRandomTypeForScore(0),e=this.getRandomTypeForScore(0),s=new Asteroid(window.innerWidth*.25,-30,t),i=new Asteroid(window.innerWidth*.75,-30,e),n=window.innerWidth/2;s.vx=(n-s.x)*.015,s.vy=60+Math.random()*40,i.vx=(n-i.x)*.015,i.vy=60+Math.random()*40,this.asteroids.push(s,i)}spawn(){const t=Math.random()*window.innerWidth,e=-30-Math.random()*100,s=this.getRandomTypeForScore(window.gameScore||0),i=new Asteroid(t,e,s),n=window.innerWidth/2;i.vx=(n-t)*.02+(Math.random()-.5)*30,i.vy=Math.abs(i.vy)||60+Math.random()*40,this.asteroids.push(i)}getRandomTypeForScore(t){const e=Math.random()*100;return e<40?"LIGHT":e<70?"MED":e<90?"BLUE":e<96?"PURPLE":"RED"}draw(t){for(const e of this.asteroids)e.draw(t)}checkBulletCollision(t){for(let e=t.length-1;e>=0;e--){const s=t[e];for(let i=this.asteroids.length-1;i>=0;i--){const n=this.asteroids[i],r=s.x-n.x,a=s.y-n.y;if(Math.sqrt(r*r+a*a)<n.radius)return t.splice(e,1),{asteroid:n,bullet:s,index:i}}}return null}remove(t){this.asteroids.splice(t,1)}getLargestAsteroid(){let t=null;for(const e of this.asteroids)(!t||e.type.level>t.type.level)&&(t=e);return t}clear(){this.asteroids=[],this.lastSpawnTime=0}}window.ASTEROID_TYPES=ASTEROID_TYPES,window.Asteroid=Asteroid,window.AsteroidManager=AsteroidManager;
